System.out.println("=== EXPLAIN SELECT ... WHERE email = ... (BEZ indeksu) ===");
print(stmt.executeQuery("EXPLAIN SELECT * FROM users WHERE email = 'user500@test.com'"));
// W planie pojawia sie: /* PUBLIC.USERS.tableScan */ - baza sprawdza
// KAZDY wiersz po kolei.

stmt.execute("CREATE INDEX idx_users_email ON users(email)");

System.out.println("=== EXPLAIN SELECT ... WHERE email = ... (PO indeksie) ===");
print(stmt.executeQuery("EXPLAIN SELECT * FROM users WHERE email = 'user500@test.com'"));
// Teraz w planie pojawia sie nazwa naszego indeksu (IDX_USERS_EMAIL)
// zamiast tableScan - baza uzyla indeksu, zeby od razu 'przeskoczyc'
// do pasujacego wiersza, zamiast przegladac wszystkie 1000.

System.out.println("=== CREATE INDEX wielokolumnowy (age, email) ===");
stmt.execute("CREATE INDEX idx_users_age_email ON users(age, email)");
// Indeks moze obejmowac WIECEJ NIZ JEDNA kolumne - przydaje sie, gdy
// czesto filtrujemy/sortujemy po tej SAMEJ parze kolumn naraz.
// Kolejnosc kolumn w indeksie wielokolumnowym MA ZNACZENIE - indeks
// (age, email) najlepiej wspiera zapytania filtrujace NAJPIERW po age.

System.out.println("=== CREATE UNIQUE INDEX na email ===");
stmt.execute("CREATE UNIQUE INDEX idx_users_email_unique ON users(email)");

try {
    stmt.execute("INSERT INTO users VALUES (1001, 'user500@test.com', 30)");
} catch (SQLException e) {
    System.out.println("Baza odrzucila duplikat (jak powinna): " + e.getMessage());
}
// UNIQUE INDEX to indeks, ktory DODATKOWO wymusza unikalnosc wartosci
// w danej kolumnie (podobnie jak ograniczenie UNIQUE) - roznica jest
// w praktyce kosmetyczna, obie tworza indeks pod spodem.
